// Simplified ELF Symbol Entry (Elf32_Sym)
typedef struct {
    uint32_t st_name;   // Index into string table
    uint32_t st_value;  // Address/Offset of symbol
    uint16_t st_shndx;  // Section Index (SHN_UNDEF, SHN_COMMON, etc.)
    unsigned char st_info; // Binding (Local, Global, Weak) & Type
} Elf_Sym;

// PE/COFF Symbol Storage Class Definition (StorageClass field)
#define SCL_EXTERN    2  // Global (usually strong)
#define SCL_STATIC    3  // Local/Internal
#define SCL_WEAKEXT  17  // Weak External (Specific to PE/COFF/XCOFF)

// Simplified Relocation Entry (Used by Linker)
typedef struct {
    uintptr_t r_offset; // Address/Offset needing modification
    uint32_t r_info;    // Packed: Symbol Index & Relocation Type
    // Linker Operation (e.g., R_386_PC32):
    // *Target = S + A - P
    // S = Symbol Value, A = Addend, P = Place (r_offset)
} Elf_Rel;

// Strong vs Weak Symbol Binding Example (GNU C)
// Strong symbol definition (cannot be redefined)
int global_data = 5;
void strong_function() {}

// Weak symbol definition (allowed to be overridden by a strong one)
__attribute__((weak)) void default_handler() {}

// Resolution Rule: Strong wins over Weak.
// Strong vs Strong definition leads to 'multiple definition' error.
